import { signal } from '@pyreon/reactivity'
import { kinetic } from '@pyreon/kinetic'

const Collapse = kinetic('div').collapse({ transition: 'height 250ms ease-out' })

export function Faq(props: { q: string; a: string }) {
  const open = signal(false)
  return (
    <section>
      <button aria-expanded={open()} onClick={() => open.update((v) => !v)}>
        {props.q}
      </button>
      <Collapse show={open()}>
        <p>{props.a}</p>
      </Collapse>
    </section>
  )
}

import { Show } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'
import { useReducedMotion } from '@pyreon/hooks'
import { kinetic } from '@pyreon/kinetic'
import { fadeUp } from '@pyreon/kinetic-presets'

const StepList = kinetic('ol').preset(fadeUp).stagger({ interval: 80, reverseLeave: true })

export function Steps() {
  const show = signal(true)
  const reduced = useReducedMotion()
  return (
    <div>
      <button onClick={() => show.update((v) => !v)}>{() => (show() ? 'Hide steps' : 'Show steps')}</button>
      <Show
        when={reduced}
        fallback={
          <StepList show={() => show()}>
            <li>Install</li>
            <li>Write a component</li>
            <li>Ship it</li>
          </StepList>
        }
      >
        <Show when={show}>
          <ol>
            <li>Install</li>
            <li>Write a component</li>
            <li>Ship it</li>
          </ol>
        </Show>
      </Show>
    </div>
  )
}

import { Show, onMount } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'
import { useReducedMotion } from '@pyreon/hooks'
import { kinetic } from '@pyreon/kinetic'
import { blurInUp } from '@pyreon/kinetic-presets'

const Reveal = kinetic('section').preset(blurInUp)

export function Feature(props: { title: string }) {
  const seen = signal(false)
  const reduced = useReducedMotion()
  let el: HTMLElement | null = null
  onMount(() => {
    const io = new IntersectionObserver(([entry]) => {
      if (entry?.isIntersecting) seen.set(true)
    })
    if (el) io.observe(el)
    return () => io.disconnect()
  })
  return (
    <div ref={(node) => { el = node }}>
      <Show
        when={reduced}
        fallback={
          <Reveal show={seen()}>
            <h2>{props.title}</h2>
          </Reveal>
        }
      >
        <section>
          <h2>{props.title}</h2>
        </section>
      </Show>
    </div>
  )
}
